  "inlineSchema": "// Approval workflow engine schema.\n// Everything is append-only for steps and audit log rows — nothing is deleted,\n// only ever superseded, so the history stays a defensible audit trail.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\nmodel User {\n  id           String   @id @default(uuid())\n  name         String\n  email        String   @unique\n  passwordHash String? // null for Google-only accounts\n  googleId     String?  @unique\n  role         String // e.g. \"direct_manager\", \"legal_reviewer\", \"cfo\" — coarse role tag used by policy templates\n  managerId    String?\n  department   String\n  createdAt    DateTime @default(now())\n\n  requestedPRs     PurchaseRequest[] @relation(\"requester\")\n  approvalSteps    ApprovalStep[]    @relation(\"approver\")\n  delegationsGiven Delegation[]      @relation(\"delegator\")\n  delegationsTaken Delegation[]      @relation(\"delegate\")\n}\n\nmodel Delegation {\n  id          String   @id @default(uuid())\n  delegatorId String\n  delegateId  String\n  startDate   DateTime\n  endDate     DateTime\n  reason      String?\n\n  delegator User @relation(\"delegator\", fields: [delegatorId], references: [id])\n  delegate  User @relation(\"delegate\", fields: [delegateId], references: [id])\n}\n\nmodel ApprovalPolicy {\n  id            String    @id @default(uuid())\n  name          String\n  priority      Int       @default(0)\n  department    String? // null = applies to any department\n  category      String? // null = applies to any category\n  amountMin     Decimal?  @db.Decimal(14, 2)\n  amountMax     Decimal?  @db.Decimal(14, 2)\n  chainTemplate Json // ordered list of { order, type, role|roles, condition? } — see routing-engine.ts\n  activeFrom    DateTime  @default(now())\n  activeUntil   DateTime?\n\n  @@index([department, category])\n}\n\nmodel PurchaseRequest {\n  id                    String   @id @default(uuid())\n  rfqId                 String?\n  quoteId               String?\n  requesterId           String\n  amount                Decimal  @db.Decimal(14, 2)\n  department            String\n  category              String\n  status                String   @default(\"draft\")\n  currentRoutingVersion Int      @default(0)\n  createdAt             DateTime @default(now())\n  updatedAt             DateTime @updatedAt\n\n  requester User               @relation(\"requester\", fields: [requesterId], references: [id])\n  steps     ApprovalStep[]\n  auditLog  ApprovalAuditLog[]\n}\n\nmodel ApprovalStep {\n  id                String    @id @default(uuid())\n  purchaseRequestId String\n  routingVersion    Int // which reconciliation pass produced this row\n  stepOrder         Int\n  stepType          String // 'sequential' | 'parallel_group'\n  groupId           String? // shared by all members of one parallel_group\n  approverRole      String\n  approverUserId    String\n  status            String    @default(\"pending\") // pending | approved | rejected | superseded\n  actedById         String?\n  actedAt           DateTime?\n  comments          String?\n  createdAt         DateTime  @default(now())\n\n  purchaseRequest PurchaseRequest @relation(fields: [purchaseRequestId], references: [id])\n  approver        User            @relation(\"approver\", fields: [approverUserId], references: [id])\n\n  @@index([purchaseRequestId, routingVersion])\n  @@index([approverUserId, status])\n}\n\n// ---- Vendor discovery -------------------------------------------------\n\nmodel Vendor {\n  id             String   @id @default(uuid())\n  name           String\n  website        String?\n  categories     String[] // tags like \"laptops\", \"industrial-equipment\"\n  certifications String[] // e.g. \"ISO9001\", \"SOC2\", \"WBENC\"\n  contactEmail   String?\n  notes          String?\n  createdAt      DateTime @default(now())\n\n  quotes           Quote[]\n  reliabilityScore ReliabilityScore?\n}\n\n// ---- RFQ / quote requests ----------------------------------------------\n\nmodel RfqEvent {\n  id          String   @id @default(uuid())\n  title       String\n  category    String\n  requesterId String\n  budget      Decimal? @db.Decimal(14, 2)\n  specNotes   String?\n  status      String   @default(\"open\") // open | comparing | awarded | cancelled\n  createdAt   DateTime @default(now())\n\n  quotes Quote[]\n}\n\nmodel Quote {\n  id             String   @id @default(uuid())\n  rfqEventId     String\n  vendorId       String\n  rawDocumentUrl String?\n  rawEmailText   String?\n  status         String   @default(\"received\") // received | extracting | needs_review | ready | stale\n  totalPrice     Decimal? @db.Decimal(14, 2)\n  currency       String   @default(\"USD\")\n  createdAt      DateTime @default(now())\n\n  rfqEvent       RfqEvent        @relation(fields: [rfqEventId], references: [id])\n  vendor         Vendor          @relation(fields: [vendorId], references: [id])\n  extractedSpecs ExtractedSpec[]\n}\n\nmodel SpecSchema {\n  id        String  @id @default(uuid())\n  category  String\n  fieldKey  String\n  fieldType String // string | number | boolean | enum\n  unit      String?\n  required  Boolean @default(false)\n\n  @@unique([category, fieldKey])\n}\n\nmodel ExtractedSpec {\n  id           String    @id @default(uuid())\n  quoteId      String\n  fieldKey     String\n  value        String\n  unit         String?\n  confidence   Float // 0..1\n  sourceSpan   String? // the exact source text the value was pulled from\n  reviewedById String?\n  reviewedAt   DateTime?\n  createdAt    DateTime  @default(now())\n\n  quote Quote @relation(fields: [quoteId], references: [id])\n\n  @@index([quoteId])\n}\n\n// ---- Vendor reliability -------------------------------------------------\n\nmodel ReliabilityScore {\n  id         String   @id @default(uuid())\n  vendorId   String   @unique\n  score      Int // 0-100\n  rationale  String // human-readable explanation, generated alongside the score\n  signals    Json // { onTimeDeliveryRate, financialHealth, certCount, reviewSummary, ... }\n  computedAt DateTime @default(now())\n\n  vendor Vendor @relation(fields: [vendorId], references: [id])\n}\n\n// ---- Negotiation ---------------------------------------------------------\n\nmodel NegotiationThread {\n  id               String   @id @default(uuid())\n  quoteId          String\n  status           String   @default(\"drafting\") // drafting | awaiting_approval | sent | vendor_responded | settled\n  targetSavingsPct Float?\n  createdAt        DateTime @default(now())\n\n  messages NegotiationMessage[]\n}\n\nmodel NegotiationMessage {\n  id           String    @id @default(uuid())\n  threadId     String\n  direction    String // outbound_draft | outbound_sent | inbound\n  body         String\n  approvedById String?\n  approvedAt   DateTime?\n  createdAt    DateTime  @default(now())\n\n  thread NegotiationThread @relation(fields: [threadId], references: [id])\n}\n\nmodel ApprovalAuditLog {\n  id                String   @id @default(uuid())\n  purchaseRequestId String\n  eventType         String // routed | rerouted | step_approved | step_rejected | finalization_blocked_reroute | approved | rejected\n  actorId           String?\n  metadata          Json\n  createdAt         DateTime @default(now())\n\n  purchaseRequest PurchaseRequest @relation(fields: [purchaseRequestId], references: [id])\n}\n",
